CREATE Proc [dbo].[GetMainStoreInventoryBalanceOfSubRecipeItem] @Sid as int as Select i.ItemId,i.Item,u.Unit,u.UId,ipl.Parlevel,isnull(dbo.uspGetItemAvgRateFunc(@Sid,i.ItemId,null,null,0),0) as Rate,iu.IssFactor as Factor From Item i inner join ItemParLevel ipl on i.ItemId=ipl.ItemId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit u on iu.PurUnit=u.Uid inner join SubCategory s on i.SBId=s.SBID where ipl.Sid = @SId and ipl.BRId=0 and s.SubCategory like 'Sub%' group by i.ItemId,i.Item,u.Unit,u.UId,ipl.Parlevel,iu.IssFactor order by i.Item